SOURCES = {'mediaengine': '# SPDX-License-Identifier: GPL-3.0-or-later\n\n"""The playback engine of one media viewer: a GstPlay and its video sink.\n\nFreeing a GstPlay can crash: SIGSEGV in\n``g_type_check_instance_is_fundamentally_a`` under ``gst_message_new_custom``\nin libgstplay. Measured, not explained: freeing it right after\n``pause()`` then ``stop()`` under a ``Gtk.MediaStream`` in a ``Gtk.Video``\ncrashed 6 of 7 twelve-cycle runs, while a plain ``stop()`` then free\nsurvived 500 cycles; the real viewer on ``main`` crashed 4 times in about\n415 open/close cycles. The precise trigger is not identified, and waiting\nfor STOPPED removed the crash in every variant tested. So an\n:class:`Engine` is never dropped directly:\n\n* ``release()`` stops the pipeline, waits for the adapter to report\n  ``STOPPED``, disconnects every handler and drops the references from an\n  idle callback;\n* until then the engine sits in ``_releasing``, so it outlives the viewer\n  that closed it;\n* at quit :func:`shutdown_all` does the same synchronously, turning the\n  main context until ``STOPPED``, because the interpreter would otherwise\n  free a playing GstPlay during teardown.\n\nHandlers are connected once, in ``__init__``, and their ids are kept so\nthat release can undo every one of them. Events reach the owner by a\nmethod call, ``owner._engine_event(name, *args)``; a closure that\ncaptured the owner would leak it (see MEMORY-LEAKS.md).\n\nThis module imports only Gst, GstPlay, GstPbutils, GLib and Gtk.\n"""\n\nimport gc\nimport time\n\nimport gi\n\ngi.require_version(\'Gtk\', \'4.0\')\ngi.require_version(\'Gst\', \'1.0\')\ngi.require_version(\'GstPlay\', \'1.0\')\ngi.require_version(\'GstPbutils\', \'1.0\')\n\nfrom gi.repository import GLib, Gst, GstPbutils, GstPlay, Gtk  # noqa: E402,F401\n\n# How long release waits for STOPPED before dropping the engine anyway.\nSTOP_TIMEOUT_MS = 1000\n\n# Engines that were asked to release and have not been dropped yet. A\n# strong reference: the engine must outlive the viewer that closed it.\n_releasing = set()\n# Every engine not yet dropped, for shutdown_all().\n_all = set()\n\n\nclass Engine:\n    """One GstPlay with its ``gtk4paintablesink``, owned by one viewer.\n\n    ``owner`` gets ``_engine_event(name, *args)`` for: ``state-changed``\n    (a ``GstPlay.PlayState``), ``position`` / ``duration`` (nanoseconds),\n    ``media-info`` (a ``PlayMediaInfo``), ``seek-done`` (position),\n    ``end-of-stream``, ``error`` (a ``GLib.Error``), ``missing-plugin``\n    (description, installer detail), ``frame`` and ``size``.\n\n    *user_agent*, when given, is set on the HTTP source of a streamed\n    URI: reverse proxies refuse the library default.\n    """\n\n    def __init__(self, owner=None, user_agent=None):\n        Gst.init(None)\n        sink = Gst.ElementFactory.make(\'gtk4paintablesink\')\n        if sink is None:\n            raise RuntimeError(\'gtk4paintablesink is not available\')\n        self.owner = owner\n        self.user_agent = user_agent\n        self.sink = sink\n        self.paintable = sink.props.paintable\n        outer = sink\n        if self.paintable.props.gl_context:\n            gl_sink = Gst.ElementFactory.make(\'glsinkbin\')\n            if gl_sink is not None:\n                gl_sink.props.sink = sink\n                outer = gl_sink\n        self.play = GstPlay.Play(\n            video_renderer=GstPlay.PlayVideoOverlayVideoRenderer.new_with_sink(\n                None, outer))\n        self.adapter = GstPlay.PlaySignalAdapter.new(self.play)\n        self.uri = None\n        self.state = GstPlay.PlayState.STOPPED\n        self.released = False\n        self._ever_loaded = False\n        # stop() asked and its STOPPED not reported yet.\n        self._stopping = False\n        # load() done and no state change reported since.\n        self._fresh = False\n        # A load that arrived while a stop was in flight.\n        self._pending_uri = None\n        self._finished = False\n        # How the engine got dropped: \'stopped\' (STOPPED arrived),\n        # \'settled\' (already STOPPED), \'timeout\' or \'never-loaded\'.\n        self.how = None\n        self._timeout = 0\n        self._stop_timeout = 0\n        self._bus = None\n        self._handlers = []\n        _all.add(self)\n\n        self._connect(self.adapter, \'state-changed\', self._on_state)\n        self._connect(self.adapter, \'position-updated\', self._on_position)\n        self._connect(self.adapter, \'duration-changed\', self._on_duration)\n        self._connect(self.adapter, \'media-info-updated\', self._on_media_info)\n        self._connect(self.adapter, \'seek-done\', self._on_seek_done)\n        self._connect(self.adapter, \'end-of-stream\', self._on_end)\n        self._connect(self.adapter, \'error\', self._on_error)\n        self._connect(self.paintable, \'invalidate-contents\', self._on_frame)\n        self._connect(self.paintable, \'invalidate-size\', self._on_size)\n        pipeline = self.play.get_pipeline()\n        self._connect(pipeline, \'source-setup\', self._on_source_setup)\n        bus = pipeline.get_bus()\n        if bus is not None:\n            bus.add_signal_watch()\n            self._bus = bus\n            self._connect(bus, \'message\', self._on_bus_message)\n\n    def _connect(self, obj, signal, callback):\n        self._handlers.append((obj, obj.connect(signal, callback)))\n\n    def _disconnect_all(self):\n        handlers, self._handlers = self._handlers, []\n        for obj, handler_id in handlers:\n            try:\n                obj.disconnect(handler_id)\n            except (TypeError, RuntimeError):\n                pass\n        if self._bus is not None:\n            self._bus.remove_signal_watch()\n            self._bus = None\n\n    def _emit(self, name, *args):\n        owner = self.owner\n        if owner is not None:\n            owner._engine_event(name, *args)\n\n    # Handlers: each only relays, so none holds the owner.\n\n    def _on_state(self, _adapter, state):\n        self.state = state\n        stopped = state == GstPlay.PlayState.STOPPED\n        if stopped:\n            self._stopping = False\n            self._clear_stop_timeout()\n        self._fresh = False\n        if self.released:\n            if stopped:\n                self._finish(\'stopped\')\n            return\n        if stopped and self._pending_uri is not None:\n            # The stop this load waited for is done; a stale STOPPED can\n            # never arrive after the new load, because it started here.\n            uri, self._pending_uri = self._pending_uri, None\n            self._start_load(uri)\n            return\n        self._emit(\'state-changed\', state)\n\n    def _on_position(self, _adapter, position):\n        self._emit(\'position\', position)\n\n    def _on_duration(self, _adapter, duration):\n        self._emit(\'duration\', duration)\n\n    def _on_media_info(self, _adapter, info):\n        self._emit(\'media-info\', info)\n\n    def _on_seek_done(self, _adapter, position):\n        self._emit(\'seek-done\', position)\n\n    def _on_end(self, _adapter):\n        self._emit(\'end-of-stream\')\n\n    def _on_error(self, _adapter, error, _details):\n        # A load that fails may never report a state change.\n        self._fresh = False\n        self._emit(\'error\', error)\n\n    def _on_frame(self, _paintable):\n        self._emit(\'frame\')\n\n    def _on_size(self, _paintable):\n        self._emit(\'size\')\n\n    def _on_source_setup(self, _pipeline, source):\n        # Runs on a GStreamer thread: set a property and touch nothing else.\n        agent = self.user_agent\n        if agent and source.find_property(\'user-agent\') is not None:\n            source.set_property(\'user-agent\', agent)\n\n    def _on_bus_message(self, _bus, message):\n        # GstPlay watches this bus from its own thread, so this handler\n        # can run there: extract what is needed and hand the rest to the\n        # main loop, like Showtime does.\n        if GstPbutils.is_missing_plugin_message(message):\n            GLib.idle_add(\n                self._emit_missing,\n                GstPbutils.missing_plugin_message_get_description(message),\n                GstPbutils.missing_plugin_message_get_installer_detail(\n                    message))\n\n    def _emit_missing(self, description, detail):\n        if not self._finished:\n            self._emit(\'missing-plugin\', description, detail)\n        return False\n\n    # Control\n\n    @property\n    def active(self):\n        return not self.released and self.play is not None\n\n    def _settled(self):\n        """STOPPED is reported and nothing is in flight: no stop pending\n        and no load whose first state change has not arrived."""\n        return (self.state == GstPlay.PlayState.STOPPED\n                and not self._stopping and not self._fresh)\n\n    def load(self, uri):\n        """Prepare *uri* and preroll it: ``pause()`` after ``set_uri``,\n        because the stream only becomes prepared from the preroll. While a\n        stop is in flight the load waits for its STOPPED."""\n        if not self.active:\n            return\n        # Set now, so a message still queued from the previous media no\n        # longer matches the URI a new stream checks against.\n        self.uri = uri\n        if self._stopping:\n            self._pending_uri = uri\n            return\n        self._start_load(uri)\n\n    def _start_load(self, uri):\n        self.uri = uri\n        self._ever_loaded = True\n        self._fresh = True\n        self.play.set_uri(uri)\n        self.play.pause()\n\n    def start(self):\n        if self.active:\n            self.play.play()\n\n    def pause(self):\n        if self.active:\n            self.play.pause()\n\n    def seek(self, position_ns):\n        if self.active:\n            self.play.seek(position_ns)\n\n    def set_audio(self, muted, volume):\n        if self.active:\n            self.play.set_mute(muted)\n            self.play.set_volume(volume)\n\n    def _request_stop(self):\n        if self._stopping or self._settled():\n            return\n        self._stopping = True\n        self.play.stop()\n\n    def stop(self):\n        """Stop the pipeline but keep the engine, for the next ``load``."""\n        if not self.active:\n            return\n        self.owner = None\n        self._request_stop()\n        if self._stopping and not self._stop_timeout:\n            self._stop_timeout = GLib.timeout_add(\n                STOP_TIMEOUT_MS, self._on_stop_timeout)\n\n    def _clear_stop_timeout(self):\n        if self._stop_timeout:\n            GLib.source_remove(self._stop_timeout)\n            self._stop_timeout = 0\n\n    def _on_stop_timeout(self):\n        # STOPPED never came: do not hold a waiting load forever.\n        self._stop_timeout = 0\n        self._stopping = False\n        self._fresh = False\n        if self._pending_uri is not None and not self.released:\n            uri, self._pending_uri = self._pending_uri, None\n            self._start_load(uri)\n        return False\n\n    # Deferred release\n\n    def release(self):\n        """Stop, wait for STOPPED, disconnect, and drop the references\n        from an idle callback. Safe to call twice."""\n        if self.released:\n            return\n        self.released = True\n        self.owner = None\n        self._pending_uri = None\n        self._clear_stop_timeout()\n        _releasing.add(self)\n        if self._settled():\n            self._finish(\'settled\' if self._ever_loaded else \'never-loaded\')\n            return\n        self._timeout = GLib.timeout_add(STOP_TIMEOUT_MS, self._on_timeout)\n        self._request_stop()\n\n    def _on_timeout(self):\n        self._timeout = 0\n        self._finish(\'timeout\')\n        return False\n\n    def _finish(self, how, immediate=False):\n        if self._finished:\n            if immediate:\n                self._drop()\n            return\n        self._finished = True\n        self.how = how\n        if self._timeout:\n            GLib.source_remove(self._timeout)\n            self._timeout = 0\n        self._clear_stop_timeout()\n        self._disconnect_all()\n        if immediate:\n            self._drop()\n        else:\n            GLib.idle_add(self._drop_idle)\n\n    def _drop_idle(self):\n        self._drop()\n        return False\n\n    def _drop(self):\n        self.play = self.adapter = self.sink = self.paintable = None\n        _releasing.discard(self)\n        _all.discard(self)\n\n\ndef shutdown_all(timeout_s=1.0):\n    """Stop every engine and wait (bounded) for STOPPED, turning the main\n    context so the adapter can report it, then drop them all. Called from\n    ``do_shutdown``: a playing GstPlay freed by interpreter teardown\n    crashed 17 quits in 50."""\n    engines = [e for e in _all if e.play is not None]\n    for engine in engines:\n        engine.released = True\n        engine.owner = None\n        engine._pending_uri = None\n        engine._clear_stop_timeout()\n        engine._request_stop()\n    context = GLib.MainContext.default()\n    deadline = time.monotonic() + timeout_s\n    while time.monotonic() < deadline:\n        # An engine that reports STOPPED finishes itself in _on_state.\n        if all(e._finished or e._settled() for e in engines):\n            break\n        if not context.iteration(False):\n            time.sleep(0.002)\n    for engine in engines:\n        engine._finish(\n            \'stopped\' if engine._settled() else \'timeout\', immediate=True)\n    gc.collect()\n', 'mediastream': '# SPDX-License-Identifier: GPL-3.0-or-later\n\n"""A ``Gtk.MediaStream`` that plays through a :class:`mediaengine.Engine`.\n\n``Gtk.Video``, ``Gtk.MediaControls`` and a ``Gtk.Picture`` showing a GIFV\nall take a ``Gtk.MediaStream``. This one forwards play, pause, seek and\naudio to the engine\'s GstPlay and draws the engine\'s\n``gtk4paintablesink`` paintable, so the widgets stay as they were.\n\n* **Prepared from the preroll**, once: ``load()`` prerolls, and the first\n  media info says which streams exist and whether the source is seekable.\n  A streamed source may not know its duration yet, so the stream waits for\n  it up to ``DURATION_WAIT_MS`` after the media info, then prepares with 0.\n  It is never prepared again; a later duration only updates the stored\n  value (the end position), not ``Gtk.MediaStream.get_duration()``.\n* **Buffering** is a property: true while the engine reports BUFFERING\n  after the stream is prepared.\n* **No seek on a source that cannot seek**: GstPlay would error out\n  ("Could not seek in resource"), so ``do_seek`` calls ``seek_failed()``\n  and never reaches the engine.\n* **After ``detach()`` every vfunc is a no-op**, so a widget that still\n  holds the stream cannot reach a GstPlay that is being released.\n"""\n\nimport gi\n\ngi.require_version(\'Gtk\', \'4.0\')\ngi.require_version(\'GstPlay\', \'1.0\')\n\nfrom .i18n import gettext as _  # noqa: E402\n\ngi.require_version(\'GstPlay\', \'1.0\')\n\nfrom gi.repository import Gio, GLib, GObject, GstPlay, Gtk  # noqa: E402\n\n# A seek that never reports completion is given up on after this long.\nSEEK_FALLBACK_MS = 2000\n\n# How long after the first media info the stream waits for a duration\n# before it is prepared with none.\nDURATION_WAIT_MS = 300\n\n# A position within this of the seek target counts as the seek having landed.\nSEEK_TOLERANCE_US = 300000\n\n# Gst.CLOCK_TIME_NONE: the duration is not known (yet).\n_CLOCK_TIME_NONE = 0xFFFFFFFFFFFFFFFF\n\n_CODECS_EXTRA_MARKERS = (\'h264\', \'h.264\', \'avc\', \'hevc\', \'h265\', \'h.265\')\n\n\ndef missing_plugin_message(description, detail):\n    """The user-facing text for a missing codec. H.264 and HEVC need the\n    ``codecs-extra`` extension of the Flatpak runtime."""\n    text = (\'%s %s\' % (description or \'\', detail or \'\')).lower()\n    if any(marker in text for marker in _CODECS_EXTRA_MARKERS):\n        # Translators: shown when a video cannot be played because the\n        # system lacks its decoder. "codecs-extra" is the name of the\n        # Flatpak extension and is not translated.\n        return _(\'This video uses a format that needs the codecs-extra \'\n                 \'extension. Install it and try again.\')\n    # Translators: {codec} is the name of the missing decoder, as GStreamer\n    # words it, for example "Vorbis audio decoder".\n    return _(\'This media needs a codec that is not installed: {codec}\').format(\n        codec=description or \'?\')\n\n\ndef _to_us(nanoseconds):\n    """Nanoseconds from GstPlay as microseconds; 0 when unknown (the\n    unsigned CLOCK_TIME_NONE, or anything negative)."""\n    if nanoseconds is None or nanoseconds < 0 \\\n            or nanoseconds >= _CLOCK_TIME_NONE:\n        return 0\n    return nanoseconds // 1000\n\n\nclass EngineStream(Gtk.MediaStream):\n    __gtype_name__ = \'BabbleEngineStream\'\n\n    # The engine is rebuffering a prepared stream.\n    buffering = GObject.Property(type=bool, default=False)\n\n    def __init__(self, engine):\n        super().__init__()\n        self.engine = engine\n        self._seekable = False\n        self._seeking = False\n        self._seek_target_us = 0\n        self._seek_timeout = 0\n        self._at_end = False\n        self._duration_us = 0\n        self._failed = False\n        self._has_audio = False\n        self._has_video = False\n        # The first media info arrived and the prepare is waiting for a\n        # duration.\n        self._pending_prepare = False\n        self._prepare_timeout = 0\n        engine.owner = self\n\n    # Lifetime\n\n    def detach(self):\n        """Let go of the engine. The owner of the engine releases it."""\n        engine, self.engine = self.engine, None\n        if self._seek_timeout:\n            GLib.source_remove(self._seek_timeout)\n            self._seek_timeout = 0\n        self._cancel_prepare_timeout()\n        self.buffering = False\n        if engine is not None and engine.owner is self:\n            engine.owner = None\n\n    # Events from the engine\n\n    def _engine_event(self, name, *args):\n        if self.engine is None:\n            return\n        getattr(self, \'_on_\' + name.replace(\'-\', \'_\'))(*args)\n\n    def _on_media_info(self, info):\n        # A stale message from the media loaded before this one.\n        if info.get_uri() != self.engine.uri:\n            return\n        # A duration-changed that came before the media info counts.\n        duration = _to_us(info.get_duration()) or self._duration_us\n        if self.is_prepared():\n            self._set_duration(duration)\n            return\n        self._seekable = bool(info.is_seekable())\n        self._has_audio = bool(info.get_audio_streams())\n        self._has_video = bool(info.get_video_streams())\n        if duration > 0:\n            self._duration_us = duration\n            self._prepare()\n        elif not self._pending_prepare:\n            self._pending_prepare = True\n            self._prepare_timeout = GLib.timeout_add(\n                DURATION_WAIT_MS, self._on_prepare_timeout)\n\n    def _prepare(self):\n        self._pending_prepare = False\n        self._cancel_prepare_timeout()\n        self.stream_prepared(self._has_audio, self._has_video,\n                             self._seekable, self._duration_us)\n\n    def _cancel_prepare_timeout(self):\n        if self._prepare_timeout:\n            GLib.source_remove(self._prepare_timeout)\n            self._prepare_timeout = 0\n\n    def _on_prepare_timeout(self):\n        self._prepare_timeout = 0\n        if self._pending_prepare and not self.is_prepared():\n            self._prepare()\n        return False\n\n    def _on_state_changed(self, state):\n        self.buffering = (self.is_prepared()\n                          and state == GstPlay.PlayState.BUFFERING)\n\n    def _on_duration(self, duration):\n        self._set_duration(_to_us(duration))\n\n    def _set_duration(self, duration):\n        """A duration reported by the engine. Before the prepare it ends\n        the wait; after it, it only updates the stored value."""\n        if duration <= 0:\n            return\n        self._duration_us = duration\n        if self._pending_prepare and not self.is_prepared():\n            self._prepare()\n\n    def _on_position(self, position):\n        # The fallback for a seek-done that never comes: only a position\n        # near the target says the seek landed, not one from before it.\n        if self._seeking and abs(position // 1000\n                                 - self._seek_target_us) <= SEEK_TOLERANCE_US:\n            self._seek_done(position)\n        # update() needs a prepared stream; a streamed source may report\n        # positions before its media info.\n        if self.is_prepared():\n            self.update(position // 1000)\n\n    def _on_seek_done(self, position):\n        self._seek_done(position)\n\n    def _seek_done(self, position):\n        if not self._seeking:\n            return\n        self._seeking = False\n        if self._seek_timeout:\n            GLib.source_remove(self._seek_timeout)\n            self._seek_timeout = 0\n        self.seek_success()\n        if self.is_prepared():\n            self.update(position // 1000)\n\n    def _on_seek_timeout(self):\n        self._seek_timeout = 0\n        if self._seeking:\n            self._seeking = False\n            self.seek_success()\n        return False\n\n    def _on_end_of_stream(self):\n        if not self.is_prepared():\n            # A clip shorter than the duration wait: prepare, then end.\n            self._prepare()\n        if self.get_loop():\n            self.engine.seek(0)\n            self.engine.start()\n            return\n        self._at_end = True\n        self.update(self._duration_us)\n        self.stream_ended()\n\n    def _on_error(self, error):\n        if not self._failed:\n            self._failed = True\n            self.gerror(error)\n\n    def _on_missing_plugin(self, description, detail):\n        if self._failed:\n            return\n        self._failed = True\n        self.gerror(GLib.Error.new_literal(\n            Gio.io_error_quark(),\n            missing_plugin_message(description, detail),\n            Gio.IOErrorEnum.NOT_SUPPORTED))\n\n    def _on_frame(self):\n        self.invalidate_contents()\n\n    def _on_size(self):\n        self.invalidate_size()\n\n    # Gtk.MediaStream vfuncs\n\n    def do_play(self):\n        if self.engine is None or self._failed:\n            return False\n        if self._at_end:\n            self._at_end = False\n            self.engine.seek(0)\n        self.engine.start()\n        return True\n\n    def do_pause(self):\n        if self.engine is not None:\n            self.engine.pause()\n\n    def do_seek(self, timestamp):\n        if self.engine is None:\n            return\n        if not self._seekable:\n            self.seek_failed()\n            return\n        self._at_end = False\n        self._seeking = True\n        self._seek_target_us = timestamp\n        if self._seek_timeout:\n            GLib.source_remove(self._seek_timeout)\n        self._seek_timeout = GLib.timeout_add(\n            SEEK_FALLBACK_MS, self._on_seek_timeout)\n        self.engine.seek(timestamp * 1000)\n\n    def do_update_audio(self, muted, volume):\n        if self.engine is not None:\n            self.engine.set_audio(muted, volume)\n\n    # Gdk.Paintable vfuncs: forwarded to the sink\'s paintable\n\n    def do_snapshot(self, snapshot, width, height):\n        if self.engine is not None and self.engine.paintable is not None:\n            self.engine.paintable.snapshot(snapshot, width, height)\n\n    def do_get_intrinsic_width(self):\n        if self.engine is None or self.engine.paintable is None:\n            return 0\n        return self.engine.paintable.get_intrinsic_width()\n\n    def do_get_intrinsic_height(self):\n        if self.engine is None or self.engine.paintable is None:\n            return 0\n        return self.engine.paintable.get_intrinsic_height()\n\n    def do_get_intrinsic_aspect_ratio(self):\n        if self.engine is None or self.engine.paintable is None:\n            return 0.0\n        return self.engine.paintable.get_intrinsic_aspect_ratio()\n'}
import sys, types, time, gc, weakref, os
import gi
gi.require_version('Gtk', '4.0'); gi.require_version('Adw', '1'); gi.require_version('Gst', '1.0')
from gi.repository import Gtk, Adw, GLib, Gst
pkg = types.ModuleType('pk'); pkg.__path__ = []; sys.modules['pk'] = pkg
i18n = types.ModuleType('pk.i18n'); i18n.gettext = lambda s: s; sys.modules['pk.i18n'] = i18n
for name, src in SOURCES.items():
    m = types.ModuleType('pk.' + name); m.__package__ = 'pk'; m.__file__ = name + '.py'
    sys.modules['pk.' + name] = m
    exec(compile(src, name + '.py', 'exec'), m.__dict__)
me = sys.modules['pk.mediaengine']; ms = sys.modules['pk.mediastream']
MODE = os.environ['MODE']
URL = {'a': 'https://mastodon.me.uk/system/media_attachments/files/117/581/332/107/689/033/original/13af5d8053337ede.mp4',
       'b': 'https://files.mastodon.social/media_attachments/files/117/587/728/606/060/718/original/cd45d56eb63e2f35.mp4'}[MODE]
UA = 'Babble/0.1 (+https://github.com/mauriciobc/Babble)'
T0 = time.monotonic()
def log(m): print('%6.2fs %s' % (time.monotonic() - T0, m), flush=True)
res = {}
class App(Adw.Application):
    def __init__(s):
        super().__init__(application_id='x.Sandbox', flags=32)
    def do_activate(s):
        win = Adw.ApplicationWindow(application=s, default_width=800, default_height=600)
        video = Gtk.Video(); win.set_content(video); win.present()
        eng = me.Engine(user_agent=UA); res['eng'] = weakref.ref(eng)
        stream = ms.EngineStream(eng)
        video.set_media_stream(stream)
        # first frame
        eng.paintable.connect('invalidate-contents', lambda *a: res.setdefault('frame', time.monotonic() - T0))
        eng.play.get_pipeline().connect('source-setup', lambda p, src: log('source-setup %s user-agent prop=%r' % (src.get_factory().get_name(), src.get_property('user-agent') if src.find_property('user-agent') else None)))
        eng.load(URL); stream.play()
        s.eng, s.stream, s.video = eng, stream, video
        GLib.timeout_add(100, s.poll)
        GLib.timeout_add(30000, s.fail)
    def sinks(s):
        out = []
        def walk(e):
            it = e.iterate_recurse()
            while True:
                r, x = it.next()
                if r == Gst.IteratorResult.OK:
                    out.append(x.get_factory().get_name() if x.get_factory() else x.get_name())
                elif r == Gst.IteratorResult.RESYNC:
                    it.resync()
                else:
                    break
        walk(s.eng.play.get_pipeline()); return out
    def poll(s):
        if 'frame' in res and 'seek' not in res:
            log('first frame at %.2fs prepared=%s dur_us=%s' % (res['frame'], s.stream.is_prepared(), s.stream.get_duration()))
            log('elements: ' + ','.join(sorted(set(s.sinks()))))
            res['seek'] = 0
            if MODE == 'a':
                s.stream.seek(10_000_000)
            GLib.timeout_add(3000 if MODE == 'a' else 5000, s.after_seek)
        return 'done' not in res
    def after_seek(s):
        log('after seek ts_us=%s playing=%s error=%s' % (s.stream.get_timestamp(), s.stream.get_playing(), s.stream.get_error()))
        pipe = s.eng.play.get_pipeline()
        log('audio sinks: ' + ','.join(sorted(x for x in s.sinks() if 'sink' in x)))
        s.stream.detach(); s.video.set_media_stream(None)
        s.eng.release(); s.eng = None; s.stream = None
        GLib.timeout_add(1500, s.check_drop)
    def check_drop(s):
        gc.collect()
        log('engine dropped: %s  releasing=%d all=%d' % (res['eng']() is None, len(me._releasing), len(me._all)))
        res['done'] = 1; s.quit()
    def fail(s):
        log('TIMEOUT no result'); s.quit(); return False
App().run([])
me.shutdown_all(); log('exit clean')
